  async function syncOneNewsSource(db,userId,src){let added=0;try{let r=await fetch(src.url,{headers:{'User-Agent':'Mozilla/5.0 (compatible; HasteRSS/1.0)'}});if(!r.ok)throw new Error('HTTP '+r.status);let xml=await r.text(),parsed=parseFeed(xml);let existingGuids=new Set(db.news.filter(x=>x.userId===userId&&x.source===src.name).map(x=>x.guid).filter(Boolean));for(const it of parsed.slice(0,30)){if(!it.guid||existingGuids.has(it.guid))continue;db.news.push({id:id(),userId,title:it.title,source:src.name,category:src.category,url:it.link||'',summary:it.summary||'',date:today(),saved:false,guid:it.guid,createdAt:Date.now()});existingGuids.add(it.guid);added++}src.lastSyncAt=Date.now();src.lastError=null;return{source:src.name,ok:true,found:parsed.length,added}}catch(e){src.lastError=e.message;return{source:src.name,ok:false,error:e.message,added:0}}}
  function periodRange(period,periodKey){if(period==='yearly')return{from:periodKey+'-01-01',to:periodKey+'-12-31'};if(period==='monthly'){let days=new Date(Number(periodKey.slice(0,4)),Number(periodKey.slice(5,7)),0).getDate();return{from:periodKey+'-01',to:periodKey+'-'+String(days).padStart(2,'0')}}let end=new Date(periodKey+'T12:00:00');end.setDate(end.getDate()+6);return{from:periodKey,to:end.toISOString().slice(0,10)}}
  function computeGoalProgress(db,userId,goal){let{from,to}=periodRange(goal.period,goal.periodKey);if(goal.linkedType==='habit'){return db.habitLogs.filter(l=>l.habitId===goal.linkedId&&l.done&&l.date>=from&&l.date<=to).length}if(goal.linkedType==='finance'){return db.transactions.filter(x=>x.userId===userId&&x.category===goal.linkedId&&x.date>=from&&x.date<=to&&x.kind==='expense').reduce((n,x)=>n+x.amount,0)}if(goal.linkedType==='learning'){let item=db.learning.find(x=>x.id===goal.linkedId&&x.userId===userId);return item&&item.progressTotal?Math.round(item.progressCurrent/item.progressTotal*100):0}return goal.manualValue||0}
